@page "/book-appointment"
@rendermode InteractiveServer
@using sv_27adaadc145d4efa8f48596e20de1e24.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1: Patient Information ───── *@
    <fieldset>
        <legend>Step 1 — Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (!string.IsNullOrEmpty(serverErrors.GetValueOrDefault("Email")))
            {
                <div class="validation-message">@serverErrors["Email"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @* ───── STEP 2: Appointment Details ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2 — Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc.Name">@doc.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (!string.IsNullOrEmpty(serverErrors.GetValueOrDefault("Doctor")))
                {
                    <div class="validation-message">@serverErrors["Doctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control"
                           @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (!string.IsNullOrEmpty(serverErrors.GetValueOrDefault("TimeSlot")))
                {
                    <div class="validation-message">@serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">
                Back
            </button>
            <button type="button" class="btn btn-primary me-2" @onclick="CheckAvailability">
                Check Availability
            </button>

            @if (isConfirmed)
            {
                <button type="submit" class="btn btn-success">
                    Confirm Appointment
                </button>
            }
        </fieldset>
    }
</EditForm>

@if (isSubmitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private List<DoctorInfo> doctors = [];
    private List<string> timeSlots = [];
    private Dictionary<string, string> serverErrors = new();
    private bool showStep2;
    private bool isConfirmed;
    private bool isSubmitted;
    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        editContext = new EditContext(Model);
        var isStep1Valid =
            !string.IsNullOrWhiteSpace(Model.PatientName) &&
            !string.IsNullOrWhiteSpace(Model.Email) &&
            IsValidEmail(Model.Email) &&
            !string.IsNullOrWhiteSpace(Model.Phone) &&
            !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (isStep1Valid)
        {
            showStep2 = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        isConfirmed = false;
        serverErrors.Clear();
        Model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            var date = DateOnly.FromDateTime(Model.AppointmentDate.Value);
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, date);
        }
        else
        {
            timeSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        isConfirmed = false;

        // Client-side step 2 validation
        var step2Valid = true;
        if (string.IsNullOrWhiteSpace(Model.Doctor))
            step2Valid = false;
        if (!Model.AppointmentDate.HasValue || Model.AppointmentDate.Value.Date <= DateTime.Today)
            step2Valid = false;
        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
            step2Valid = false;
        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
            step2Valid = false;
        if (Model.ReasonForVisit?.Length > 500)
            step2Valid = false;

        if (!step2Valid)
            return;

        var result = await AppointmentService.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

        if (!result.IsValid)
        {
            foreach (var err in result.Errors)
                serverErrors[err.Key] = err.Value;
        }
        else
        {
            isConfirmed = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        isConfirmed = false;
        serverErrors.Clear();
    }

    private void HandleSubmit()
    {
        if (isConfirmed)
        {
            isSubmitted = true;
        }
    }

    // ── View-model with DataAnnotations ──
    public class AppointmentModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required.")]
        public string PatientName { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required.")]
        [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format.")]
        public string Email { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required.")]
        public string Phone { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required.")]
        public string InsuranceProvider { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Doctor is required.")]
        public string Doctor { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required.")]
        public DateTime? AppointmentDate { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Time slot is required.")]
        public string TimeSlot { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason for visit is required.")]
        [System.ComponentModel.DataAnnotations.MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
        public string ReasonForVisit { get; set; } = string.Empty;
    }
}

